import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-3.x/multi-tenancy.html","title":"Multi-Tenancy","lang":"en-US","frontmatter":{"title":"Multi-Tenancy"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-3.x/multi-tenancy.md"}`),u={name:`multi-tenancy.md`},d={class:`hint-container warning`};function f(s,l,u,f,p,m){let h=a(`RouteLink`);return n(),o(`div`,null,[l[39]||=e(`h1`,{id:`multi-tenancy`,tabindex:`-1`},[e(`a`,{class:`header-anchor`,href:`#multi-tenancy`},[e(`span`,null,`Multi-Tenancy`)])],-1),l[40]||=e(`p`,null,[r(`Quartz has no `),e(`code`,null,`Tenant`),r(` concept. What it has are three separations you can build one out of — a scheduler, a group, and a `),e(`code`,null,`SCHED_NAME`),r(` — and this page is about picking the right one and knowing exactly what it does and does not isolate.`)],-1),e(`p`,null,[l[1]||=r(`If you have not yet chosen a model, read `,-1),c(h,{to:`/documentation/tenancy-patterns.html`},{default:i(()=>[...l[0]||=[r(`Tenancy Patterns`,-1)]]),_:1}),l[2]||=r(` first: it surveys how other schedulers partition tenants and names the axes that decide. This page is the 3.x mechanics.`,-1)]),l[41]||=t(`<h2 id="choosing-a-model" tabindex="-1"><a class="header-anchor" href="#choosing-a-model"><span>Choosing a model</span></a></h2><table><thead><tr><th></th><th>Scheduler per tenant</th><th>Group per tenant</th><th>Database or prefix per tenant</th></tr></thead><tbody><tr><td><strong>Isolation</strong></td><td>strongest: separate job store, thread pool, listeners, plugins, calendars</td><td>logical only — one scheduler, one pool</td><td>strongest at rest; one process still runs them all</td></tr><tr><td><strong>Tenants known at</strong></td><td>startup, or runtime outside the container</td><td>any time</td><td>startup</td></tr><tr><td><strong>Add a tenant at runtime</strong></td><td>yes, but you own its lifetime</td><td>yes</td><td>no</td></tr><tr><td><strong>Per-tenant concurrency limits</strong></td><td>yes, naturally</td><td>yes, via execution groups</td><td>yes</td></tr><tr><td><strong>Cost per tenant</strong></td><td>a scheduling loop, a connection pool, a thread pool</td><td>~nothing</td><td>a schema</td></tr><tr><td><strong>Fits</strong></td><td>tens of tenants, strong isolation needs</td><td>hundreds or thousands of tenants</td><td>regulatory separation of data</td></tr></tbody></table><p>They compose. The common shape for a SaaS with many small tenants is <em>one</em> scheduler, groups per tenant, one database — and a second scheduler for the handful of tenants that bought isolation.</p><h2 id="scheduler-per-tenant" tabindex="-1"><a class="header-anchor" href="#scheduler-per-tenant"><span>Scheduler per tenant</span></a></h2><p><code>AddQuartz(name, …)</code> registers a named scheduler. The name becomes that scheduler&#39;s <code>quartz.scheduler.instanceName</code>, the name of its <code>QuartzOptions</code>, and — with a persistent store — its <code>SCHED_NAME</code>, so its configuration and its rows always agree.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> tenant <span class="token keyword">in</span> tenants<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>tenant<span class="token punctuation">,</span> q <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>sqlServer <span class="token operator">=&gt;</span> sqlServer<span class="token punctuation">.</span>ConnectionString <span class="token operator">=</span> connectionStrings<span class="token punctuation">[</span>tenant<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            s<span class="token punctuation">.</span><span class="token function">UseSystemTextJsonSerializer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            s<span class="token punctuation">.</span><span class="token function">UseClustering</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token function">UseDefaultThreadPool</span><span class="token punctuation">(</span>tp <span class="token operator">=&gt;</span> tp<span class="token punctuation">.</span>MaxConcurrency <span class="token operator">=</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>NightlyReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>trigger <span class="token operator">=&gt;</span> trigger</span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">,</span> tenant<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 30 2 * * ?&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzHostedService</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>WaitForJobsToComplete <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>One <code>AddQuartzHostedService</code> starts them all. Behind that single call sit up to two hosted services: one that enumerates every named scheduler, always registered, and one for the default scheduler, registered only when an unnamed <code>AddQuartz()</code> has already put <code>ISchedulerFactory</code> in the container.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Order matters. <code>AddQuartz()</code> must be called <strong>before</strong> <code>AddQuartzHostedService()</code> for the <em>default</em> scheduler, because the default hosted service is only registered when <code>ISchedulerFactory</code> is already in the service collection. Named schedulers are unaffected by the ordering.</p></div><p>Setting <code>SchedulerName</code> inside a named <code>AddQuartz(name, …)</code> block throws — the name is the registration key and cannot drift from it.</p><h3 id="getting-one-back" tabindex="-1"><a class="header-anchor" href="#getting-one-back"><span>Getting one back</span></a></h3><p>There is no keyed <code>IScheduler</code> on 3.x. Named schedulers are not registered in the container at all; they are created by the hosted service and bound into the repository. Inject <code>Quartz.Spi.ISchedulerRepository</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">TenantOpsService</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">ISchedulerRepository</span> schedulerRepository<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">TenantOpsService</span><span class="token punctuation">(</span><span class="token class-name">ISchedulerRepository</span> schedulerRepository<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>schedulerRepository <span class="token operator">=</span> schedulerRepository<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">TriggerNightly</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> tenant<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">IScheduler<span class="token punctuation">?</span></span> scheduler <span class="token operator">=</span> schedulerRepository<span class="token punctuation">.</span><span class="token function">Lookup</span><span class="token punctuation">(</span>tenant<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>scheduler <span class="token keyword">is</span> <span class="token keyword">not</span> <span class="token keyword">null</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">TriggerJob</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobKey</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">,</span> tenant<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p><code>ISchedulerFactory</code> is only registered when an unnamed <code>AddQuartz()</code> call has been made. In a container holding only named schedulers there is no <code>ISchedulerFactory</code> to inject — use <code>ISchedulerRepository</code>.</p><p>Named schedulers appear in the repository only once the hosted service has created and started them, so they are not there during application startup.</p></div><p>There are <strong>two</strong> repositories, and mixing them up is the most common 3.x multi-scheduler mistake. <code>SchedulerRepository.Instance</code> is a process-wide static that <code>StdSchedulerFactory</code> and <code>DirectSchedulerFactory</code> bind into by default. The DI integration registers its <em>own</em><code>ISchedulerRepository</code> singleton in the container, and the named-scheduler factory binds there instead. A scheduler created through DI is therefore <strong>not</strong> in <code>SchedulerRepository.Instance</code>, and a scheduler created by a bare <code>StdSchedulerFactory</code> is <strong>not</strong> in the container&#39;s repository — nor, consequently, in the Dashboard&#39;s scheduler list. Always inject <code>ISchedulerRepository</code> in a DI application; never reach for the static.</p><h3 id="what-is-per-scheduler" tabindex="-1"><a class="header-anchor" href="#what-is-per-scheduler"><span>What is per scheduler</span></a></h3><p>Each named scheduler gets its own job store, thread pool, listeners, plugins, calendars, jobs and triggers. Listeners and calendars registered inside a named <code>AddQuartz(name, …)</code> block are attached to that scheduler only. Plugins configured by <code>quartz.plugin.*</code> properties are instantiated once per scheduler, from that scheduler&#39;s own property bag, so <code>q.UseXmlSchedulingConfiguration(...)</code>, <code>q.UseJobAutoInterrupt(...)</code> and the rest all work inside a named block.</p><p><code>QuartzOptions</code> are <em>named options</em> whose name is the scheduler&#39;s name, which is what <code>builder.Services.Configure&lt;QuartzOptions&gt;(&quot;DurableScheduler&quot;, …)</code> binds to. Note that unlike 4.x, 3.x does not have per-scheduler <code>ThreadPoolOptions</code> or <code>AdoJobStoreOptions</code> — a named scheduler&#39;s components are configured through <code>quartz.*</code> properties on its own builder.</p><h3 id="what-is-not" tabindex="-1"><a class="header-anchor" href="#what-is-not"><span>What is not</span></a></h3><ul><li><strong><code>QuartzHostedServiceOptions</code> is global.</strong> <code>WaitForJobsToComplete</code>, <code>StartDelay</code> and <code>AwaitApplicationStarted</code> apply to every scheduler uniformly; there is no <code>AddQuartzHostedService(name, …)</code> overload on 3.x.</li><li><strong>Job types are shared.</strong> See <a href="#per-tenant-services-inside-a-job">per-tenant services inside a job</a>.</li><li><strong><code>scheduler.Context[&quot;Quartz.ServiceProvider&quot;]</code> is set only for the default scheduler.</strong> A plugin that reaches for the container through the scheduler context works on the default scheduler and silently does not on a named one.</li><li><strong>The health check covers the default scheduler only.</strong> See <a href="#health-checks-and-observability">health checks</a>.</li></ul><p>A named scheduler colliding with a default scheduler renamed to the same string is not caught at registration; it surfaces at host start as a <code>SchedulerException</code> reading <code>Scheduler with name &#39;X&#39; already exists.</code> from the repository. Two named schedulers with the same name <em>are</em> caught at registration — but only when the names match exactly. The registration check compares ordinally while the repository compares case-insensitively, so <code>AddQuartz(&quot;Acme&quot;)</code> beside <code>AddQuartz(&quot;acme&quot;)</code> passes registration and fails at start. Derive tenant scheduler names from a single normalised source.</p><h2 id="group-per-tenant" tabindex="-1"><a class="header-anchor" href="#group-per-tenant"><span>Group per tenant</span></a></h2><p>One scheduler; the tenant is the group half of every key.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">JobKey</span> job <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-report&quot;</span><span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">TriggerKey</span> trigger <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Everything that takes a <code>GroupMatcher</code> then becomes tenant-scoped:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// everything this tenant has scheduled</span></span>
<span class="line"><span class="token class-name">IReadOnlyCollection<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> theirs <span class="token operator">=</span></span>
<span class="line">    <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetTriggerKeys</span><span class="token punctuation">(</span>GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// suspend a tenant</span></span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">PauseTriggers</span><span class="token punctuation">(</span>GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// is a tenant suspended?</span></span>
<span class="line"><span class="token class-name">IReadOnlyCollection<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">&gt;</span></span> paused <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetPausedTriggerGroups</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">bool</span></span> suspended <span class="token operator">=</span> paused<span class="token punctuation">.</span><span class="token function">Contains</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// or, directly</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">bool</span></span> alsoSuspended <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">IsTriggerGroupPaused</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// offboard a tenant</span></span>
<span class="line"><span class="token class-name">IReadOnlyCollection<span class="token punctuation">&lt;</span>JobKey<span class="token punctuation">&gt;</span></span> jobs <span class="token operator">=</span></span>
<span class="line">    <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetJobKeys</span><span class="token punctuation">(</span>GroupMatcher<span class="token operator">&lt;</span>JobKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">DeleteJobs</span><span class="token punctuation">(</span>jobs<span class="token punctuation">.</span><span class="token function">ToList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>GroupMatcher&lt;TKey&gt;</code> also offers <code>GroupStartsWith</code>, <code>GroupEndsWith</code>, <code>GroupContains</code> and <code>AnyGroup</code>, and <code>AndMatcher</code> / <code>OrMatcher</code> / <code>NotMatcher</code> compose them.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Pause tenants by <strong>trigger</strong> group. The ADO.NET job store does not persist paused <em>job</em> group state — <code>IsJobGroupPaused</code> always returns <code>false</code> there, because <code>PauseJobs</code> pauses the individual triggers of the jobs in the group without recording the group itself. <code>RAMJobStore</code> does track it, so the two stores differ; write against the persistent behaviour.</p></div><p>Listeners take matchers too, so a per-tenant listener is one registration:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobListener</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>AuditListener<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>GroupMatcher<span class="token operator">&lt;</span>JobKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Several matchers on one listener are OR-ed. Matchers can be added and removed at runtime through <code>IListenerManager.AddJobListenerMatcher</code> / <code>RemoveJobListenerMatcher</code> / <code>SetJobListenerMatchers</code>. Scheduler listeners are not matchable — a tenant-scoped <code>ISchedulerListener</code> is not expressible.</p><p><code>DeleteJobs</code>, <code>UnscheduleJobs</code> and <code>ScheduleJobs</code> take key collections rather than matchers on 3.x, which is why offboarding is the two-step above. <code>Clear()</code> takes no matcher at all: it empties the whole scheduler, never one tenant.</p><p>Calendars are a flat namespace within a scheduler — there is no calendar group. Under group-per-tenant, tenants share it and must namespace the names themselves (<code>&quot;acme:holidays&quot;</code>).</p><h3 id="per-tenant-concurrency-quotas" tabindex="-1"><a class="header-anchor" href="#per-tenant-concurrency-quotas"><span>Per-tenant concurrency quotas</span></a></h3><p>Execution groups cap how many threads a category of work may use on a node. Give each tenant an execution group and a limit:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span> limits</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">8</span><span class="token punctuation">)</span>      <span class="token comment">// a big tenant</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;initech&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// everyone else gets one thread each</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>or as properties:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">quartz.executionLimit.acme = 8</span>
<span class="line">quartz.executionLimit.initech = 2</span>
<span class="line">quartz.executionLimit.* = 1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>On 3.x the execution group is a <strong>separate tag on the trigger</strong>; it is not derived from the trigger group. Every trigger for a tenant must carry it explicitly:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithExecutionGroup</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span>      <span class="token comment">// &lt;- required; the key group is not consulted</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 30 2 * * ?&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Quartz 4.x adds <code>UseTriggerGroupWhenUnset()</code>, which lets the trigger group stand in for the execution group so that no trigger has to repeat it. There is no 3.x equivalent — forget the tag on one trigger and that trigger runs unlimited, or falls into whatever <code>ForOtherGroups</code> allows.</p></div>`,38),e(`div`,d,[l[8]||=e(`p`,{class:`hint-container-title`},`Warning`,-1),e(`p`,null,[l[4]||=t(`<code>WithExecutionGroup</code> is on <code>TriggerBuilder</code>, <strong>not</strong> on the DI <code>ITriggerConfigurator</code>. So <code>q.AddTrigger(t =&gt; t.WithExecutionGroup(&quot;acme&quot;))</code> does not compile, and neither does the <code>q.ScheduleJob&lt;T&gt;(trigger =&gt; …)</code> form. Triggers that need an execution group must be built with <code>TriggerBuilder</code> and passed to <code>scheduler.ScheduleJob(...)</code> at runtime, or declared through `,16),c(h,{to:`/documentation/quartz-3.x/packages/json-configuration.html`},{default:i(()=>[...l[3]||=[r(`JSON scheduling`,-1)]]),_:1}),l[5]||=r(`, where `,-1),l[6]||=e(`code`,null,`ExecutionGroup`,-1),l[7]||=r(` is a recognised property on a trigger definition.`,-1)]),l[9]||=e(`p`,null,[r(`Reading it back has the same asymmetry: `),e(`code`,null,`ITrigger`),r(` does not declare `),e(`code`,null,`ExecutionGroup`),r(` on 3.x, so `),e(`code`,null,`(await scheduler.GetTrigger(key)).ExecutionGroup`),r(` does not compile either — cast to `),e(`code`,null,`Quartz.Impl.Triggers.AbstractTrigger`),r(`.`)],-1)]),l[42]||=t(`<p>Limits can also be changed at runtime, per node:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">SetExecutionLimits</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">ExecutionLimits</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> <span class="token number">8</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>SetExecutionLimits</code> and <code>GetExecutionLimits</code> are <strong>extension methods</strong> on <code>IScheduler</code>, not interface members, and they require the scheduler to be a <code>StdScheduler</code>. Against a <code>RemoteScheduler</code> or a custom <code>IScheduler</code> they throw a <code>SchedulerException</code>. Limits take effect on the next acquisition cycle; pass <code>null</code> to clear them.</p>`,3),e(`p`,null,[l[11]||=r(`With an ADO.NET job store, persisting a trigger's execution group needs an `,-1),l[12]||=e(`code`,null,`EXECUTION_GROUP`,-1),l[13]||=r(` column on `,-1),l[14]||=e(`code`,null,`QRTZ_TRIGGERS`,-1),l[15]||=r(`. The column is optional on 3.x — the store probes for it at startup and logs at Debug level when it is missing — but without it nothing is persisted and every trigger looks ungrouped after a restart. See `,-1),c(h,{to:`/documentation/quartz-3.x/tutorial/execution-groups.html`},{default:i(()=>[...l[10]||=[r(`Execution Groups`,-1)]]),_:1}),l[16]||=r(` for the DDL.`,-1)]),l[43]||=t(`<div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Execution limits are <strong>per node</strong>, held in memory, and nothing about them is persisted or coordinated. On a three-node cluster, a limit of 8 for <code>acme</code> means up to 24 concurrent Acme jobs. See <a href="#honest-limits">honest limits</a>.</p></div><h3 id="pinning-a-tenant-to-hardware" tabindex="-1"><a class="header-anchor" href="#pinning-a-tenant-to-hardware"><span>Pinning a tenant to hardware</span></a></h3>`,2),e(`p`,null,[c(h,{to:`/documentation/quartz-3.x/tutorial/node-affinity.html`},{default:i(()=>[...l[17]||=[r(`Node affinity`,-1)]]),_:1}),l[18]||=r(` is the other per-tenant cluster control, and unlike execution limits it `,-1),l[19]||=e(`em`,null,`is`,-1),l[20]||=r(` persisted. `,-1),l[21]||=e(`code`,null,`TriggerBuilder.WithPreferredNode(instanceId)`,-1),l[22]||=r(` records which node should pick a trigger up, with failover to another node if the preferred one is down. Where execution limits say "how much of this node may this tenant use", node affinity says "which nodes are this tenant's" — which is usually the more useful question when tenants have bought dedicated capacity.`,-1)]),l[44]||=t(`<p>Node affinity needs a stable <code>quartz.scheduler.instanceId</code>. <code>AUTO</code> generates a fresh id on every restart, and the store logs a warning when it detects one.</p><h2 id="shared-database" tabindex="-1"><a class="header-anchor" href="#shared-database"><span>Shared database</span></a></h2><p>Every Quartz table has <code>SCHED_NAME</code> as the first column of its primary key, and every statement filters on it. Two schedulers with different names therefore share tables without seeing each other&#39;s rows, and that is a property of the schema rather than of the code paths — there is no query that forgets. <code>SCHED_NAME</code> is bound to <code>quartz.scheduler.instanceName</code>; the only statements that do not carry it are the schema probes, which select no rows.</p><p>Table prefix is the other axis. <code>quartz.jobStore.tablePrefix</code> (default <code>QRTZ_</code>) is a per-scheduler setting, so two tenants can have entirely separate table <em>sets</em> in one database:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>sqlServer <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        sqlServer<span class="token punctuation">.</span>ConnectionString <span class="token operator">=</span> sharedConnectionString<span class="token punctuation">;</span></span>
<span class="line">        sqlServer<span class="token punctuation">.</span>TablePrefix <span class="token operator">=</span> <span class="token string">&quot;ACME_QRTZ_&quot;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    s<span class="token punctuation">.</span><span class="token function">UseSystemTextJsonSerializer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Three rules:</p><ul><li><strong>Different scheduler name is enough.</strong> Prefixes are for keeping tenants in separate <em>tables</em>, which is a backup-and-restore or a permissions decision, not an isolation one.</li><li><strong>The prefix has to match the DDL.</strong> Nothing derives one from the other; you run the DDL with the prefix substituted.</li><li><strong>A wrong prefix is caught at startup.</strong> <code>PerformSchemaValidation</code> is on by default, so a missing or mis-prefixed table is reported at startup rather than surfacing as the first failing operation an hour later.</li></ul><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Two schedulers sharing a database with the <strong>same</strong> <code>SCHED_NAME</code> are, by construction, indistinguishable from two nodes of one cluster — because that is exactly what they look like to the schema. Schema validation will not catch it, and they will steal each other&#39;s triggers. The duplicate-name check protects you only within one container; across processes, the name is a contract you keep.</p><p><code>instanceName</code> identifies the <em>logical</em> scheduler and is what tenants differ by. <code>instanceId</code> identifies a <em>node</em> of one logical scheduler, and is what cluster members differ by. Getting these the wrong way round is what produces the failure above.</p></div><p>Also worth knowing: with a persistent store, <code>[DisallowConcurrentExecution]</code> is enforced cluster-wide by counting rows in <code>QRTZ_FIRED_TRIGGERS</code> — but that count is filtered by <code>SCHED_NAME</code>, so it does not reach across tenants. That is the intended behaviour, and it means two tenants can each run their own copy of the same job type concurrently.</p><p>If you use the Redis lock handler, its keys already include the scheduler name, so a shared Redis is safe across tenants that differ by <code>SCHED_NAME</code>.</p><h2 id="per-tenant-services-inside-a-job" tabindex="-1"><a class="header-anchor" href="#per-tenant-services-inside-a-job"><span>Per-tenant services inside a job</span></a></h2><p>A job needs to reach <em>its</em> tenant&#39;s database, its tenant&#39;s configuration, its tenant&#39;s feature flags. <code>MicrosoftDependencyInjectionJobFactory</code> creates a DI scope for every job execution — unconditionally on 3.x, the older <code>CreateScope</code> and <code>AllowDefaultConstructor</code> options are obsolete and ignored — and the scope is prepared before the job and everything it injects are constructed.</p><p>The hook is <code>protected virtual void ConfigureScope(IServiceScope, TriggerFiredBundle, IScheduler)</code>, reached by subclassing:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TenantJobFactory</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">MicrosoftDependencyInjectionJobFactory</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">TenantJobFactory</span><span class="token punctuation">(</span><span class="token class-name">IServiceProvider</span> serviceProvider<span class="token punctuation">,</span> <span class="token class-name">IOptions<span class="token punctuation">&lt;</span>QuartzOptions<span class="token punctuation">&gt;</span></span> options<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">:</span> <span class="token keyword">base</span><span class="token punctuation">(</span>serviceProvider<span class="token punctuation">,</span> options<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">protected</span> <span class="token keyword">override</span> <span class="token return-type class-name"><span class="token keyword">void</span></span> <span class="token function">ConfigureScope</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name">IServiceScope</span> scope<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">TriggerFiredBundle</span> bundle<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        scope<span class="token punctuation">.</span>ServiceProvider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TenantHolder<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>TenantId <span class="token operator">=</span> bundle<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddScoped</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TenantHolder<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">UseJobFactory</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TenantJobFactory<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Quartz 4.x</p><p>Quartz 4.x adds <code>q.ConfigureJobScope((scope, bundle, scheduler) =&gt; …)</code>, a delegate registration that needs no subclass and whose callbacks combine. There is no 3.x equivalent; subclassing is the way.</p></div><p>Two things make this work, and both are worth knowing:</p><ul><li><strong>The hook is synchronous.</strong> An asynchronous hook would be awaited, and the <code>ExecutionContext</code> restored on the way back would discard exactly the <code>AsyncLocal&lt;T&gt;</code> values it exists to set. Both the scoped-holder pattern above and an <code>AsyncLocal&lt;T&gt;</code> work; the holder is easier to test and does not depend on execution context flow.</li><li><strong>The job is created on the execution path</strong>, not during initialization, so values set here flow into <code>Execute</code>.</li></ul><p>The <code>TriggerFiredBundle</code> gives you the whole firing to derive the tenant from — <code>Trigger.Key.Group</code>, <code>JobDetail.Key.Group</code>, or a value out of <code>Trigger.JobDataMap</code> — plus the <code>IScheduler</code> that fired it, which is the tenant itself under the scheduler-per-tenant model. Inside <code>Execute</code>, the same identity is available from <code>context.Trigger.Key.Group</code> or <code>context.MergedJobDataMap</code>.</p><p>Alternatively, read the tenant inside the job and resolve per-tenant services by key. Quartz 3.x makes no keyed registrations of its own, but keyed lookups pass through the job&#39;s scope, so your own keyed services resolve:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ReportJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">IServiceProvider</span> services<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">ReportJob</span><span class="token punctuation">(</span><span class="token class-name">IServiceProvider</span> services<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>services <span class="token operator">=</span> services<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">string</span></span> tenant <span class="token operator">=</span> context<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">;</span></span>
<span class="line">        <span class="token class-name">ITenantStore</span> store <span class="token operator">=</span> services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredKeyedService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ITenantStore<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>tenant<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">await</span> store<span class="token punctuation">.</span><span class="token function">WriteReport</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>CancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Keyed services require <code>Microsoft.Extensions.DependencyInjection</code> 8.0 or later, so this pattern needs an application on <code>net8.0</code> or newer — Quartz 3.x itself still supports <code>netstandard2.0</code> and .NET Framework, where it is unavailable.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Registering a job type keyed does <strong>not</strong> work. The job factory resolves the job type unkeyed from the scope and falls back to direct activation when nothing is registered, so a keyed job-type registration is silently never consulted. Key the job&#39;s <em>dependencies</em>, not the job.</p></div><p>For anything more involved — resolving jobs from a tenant-owned container, say — implement <code>Quartz.Spi.IJobFactory</code> directly (<code>IJob NewJob(TriggerFiredBundle bundle, IScheduler scheduler)</code> plus <code>void ReturnJob(IJob job)</code>) and register it with <code>q.UseJobFactory&lt;T&gt;()</code>. On Quartz 4.x that interface is in <code>Quartz.Extensibility</code> and returns a <code>ValueTask&lt;JobScope&gt;</code>, so a custom factory does not port across unchanged.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>On a <strong>named</strong> scheduler, <code>UseJobFactory&lt;T&gt;()</code> configures the factory by property and deliberately does not replace the container&#39;s global singleton, so the type is constructed by the named scheduler&#39;s own factory rather than resolved as a registered service. Make sure its constructor dependencies are registered in the container.</p></div><h2 id="health-checks-and-observability" tabindex="-1"><a class="header-anchor" href="#health-checks-and-observability"><span>Health checks and observability</span></a></h2><p><strong>Health checks are not per tenant on 3.x.</strong> <code>AddQuartzServer</code> registers a single health check named <code>quartz-scheduler</code>, which resolves the <strong>default</strong> scheduler from <code>ISchedulerFactory</code>, checks that it is started and performs one store round-trip. Named schedulers are not covered, the check type is internal so it cannot be registered again by hand, and on <code>netstandard2.0</code> there is no health check at all.</p><p>Note the consequence for a scheduler-per-tenant container: the check is registered unconditionally, but it resolves <code>ISchedulerFactory</code>, which a container holding <strong>only</strong> named schedulers never registers. If you use <code>AddQuartzServer</code> without a default scheduler, either register a default one or use <code>AddQuartzHostedService</code> and write your own check.</p><p>Tags are the only knob on the built-in one:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartzServer</span><span class="token punctuation">(</span></span>
<span class="line">    options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>WaitForJobsToComplete <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token named-parameter punctuation">healthCheckTags</span><span class="token punctuation">:</span> <span class="token keyword">new</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">{</span> <span class="token string">&quot;ready&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>For per-tenant health, write your own <code>IHealthCheck</code> that injects <code>ISchedulerRepository</code> and walks the schedulers you care about.</p><div class="hint-container tip"><p class="hint-container-title">Quartz 4.x</p><p>Quartz 4.x adds <code>AddQuartzHealthChecks</code> on a scheduler&#39;s own builder, defaulting the check name to <code>quartz-scheduler-&lt;scheduler name&gt;</code> so several can be registered side by side.</p></div><p><strong>Traces</strong> come from <code>DiagnosticListener</code> and <code>Activity</code>, under the listener name <code>Quartz</code>. The tag names are public constants on <code>Quartz.Logging.DiagnosticHeaders</code>:</p><table><thead><tr><th>Constant</th><th>Tag</th></tr></thead><tbody><tr><td><code>DiagnosticHeaders.SchedulerName</code></td><td><code>scheduler.name</code></td></tr><tr><td><code>DiagnosticHeaders.SchedulerId</code></td><td><code>scheduler.id</code></td></tr><tr><td><code>DiagnosticHeaders.FireInstanceId</code></td><td><code>fire.instance.id</code></td></tr><tr><td><code>DiagnosticHeaders.TriggerGroup</code></td><td><code>trigger.group</code></td></tr><tr><td><code>DiagnosticHeaders.TriggerName</code></td><td><code>trigger.name</code></td></tr><tr><td><code>DiagnosticHeaders.JobGroup</code></td><td><code>job.group</code></td></tr><tr><td><code>DiagnosticHeaders.JobName</code></td><td><code>job.name</code></td></tr><tr><td><code>DiagnosticHeaders.JobType</code></td><td><code>job.type</code></td></tr></tbody></table><p>Under scheduler-per-tenant the tenant is <code>scheduler.name</code>; under group-per-tenant it is <code>job.group</code> and <code>trigger.group</code>. That is a good reason to make the group the raw tenant id rather than a decorated string.</p><div class="hint-container warning"><p class="hint-container-title">Cardinality</p><p><code>job.name</code> and <code>trigger.name</code> are per job and per trigger. Multiply that by a tenant dimension and a backend can find itself with a series per tenant per trigger. Drop the name tags before they reach the backend unless you know you need them.</p></div><p>Two gaps to plan around:</p><ul><li><strong>There are no metrics on 3.x.</strong> Quartz 3.x publishes no <code>Meter</code> and no counters or histograms; the 4.x <code>quartz.job.execution.*</code> instruments have no 3.x counterpart. Traces, and your own instrumentation, are what you have.</li><li><strong>Nothing puts the tenant into a logging scope.</strong> If you want every log line a job writes to carry its tenant, open an <code>ILogger.BeginScope</code> yourself — in <code>Execute</code>, in a job base class, or in a custom job factory. <code>q.UseStructuredJobLogging()</code> and <code>q.UseStructuredTriggerLogging()</code> emit Quartz&#39;s own history entries with named parameters, which helps, but they do not scope your job&#39;s logging.</li></ul><h2 id="honest-limits" tabindex="-1"><a class="header-anchor" href="#honest-limits"><span>Honest limits</span></a></h2><p>Things multi-tenant deployments ask Quartz for and do not get.</p>`,40),e(`p`,null,[l[24]||=e(`strong`,null,`Execution limits are per node, not cluster-wide.`,-1),l[25]||=r(` The running count for each execution group lives in a dictionary in memory on the scheduler thread. Nothing is persisted and nodes do not coordinate. A cluster-wide cap is not available; the closest approximation is dividing the cap by the node count, which is wrong whenever a node is down. For a cluster-aware per-tenant control, use `,-1),c(h,{to:`/documentation/quartz-3.x/tutorial/node-affinity.html`},{default:i(()=>[...l[23]||=[r(`node affinity`,-1)]]),_:1}),l[26]||=r(` instead — it is persisted.`,-1)]),l[45]||=t(`<p><strong>There is no rate limiting.</strong> Execution limits cap <em>concurrency</em>, not throughput. &quot;This tenant may run 100 jobs an hour&quot; is not something Quartz can express; build it in the job, or in the thing the job calls.</p><p><strong>A starved group&#39;s triggers misfire; they do not queue.</strong> When a group is at its limit its triggers are skipped during acquisition and left as they are, keeping their original next fire time. If the starvation outlasts the misfire threshold, the ordinary misfire machinery claims them and the trigger&#39;s misfire instruction decides whether the occurrence is skipped or rescheduled. Choose misfire instructions deliberately for triggers in limited groups.</p><p><strong>Job types are shared across schedulers.</strong> Job classes are resolved unkeyed from the one container, so two schedulers cannot register different implementations for the same job type. Give each tenant its own job type, or — far better — one job type that reads its tenant from the firing.</p><p><strong>Nothing stops a job reaching another tenant&#39;s data.</strong> <code>IJobExecutionContext.Scheduler</code> hands the running job the whole scheduler, with <code>DeleteJob</code>, <code>PauseTriggers</code> and <code>Clear</code> on it. There is no group-scoped scheduler façade and no authorization hook. Group-per-tenant is a naming convention with tooling support, not an enforcement boundary. If tenant code must not be able to reach across, that is a process boundary, not a group.</p><p><strong>Dashboard authorization is per process, all or nothing.</strong> The Dashboard has one <code>AuthorizationPolicy</code>, one <code>IDashboardAuthorizationFilter</code> and one <code>ReadOnly</code> flag; there is no per-scheduler policy and no scheduler-name claim check, even though its scheduler selector lists every scheduler in the repository. If tenants must reach their own scheduler and not each other&#39;s, enforce that outside Quartz.</p><p><strong>A shut-down scheduler cannot be restarted.</strong> <code>Start()</code> on a shut-down scheduler throws <code>The Scheduler cannot be restarted after Shutdown() has been called.</code>, and every other operation throws <code>The Scheduler has been Shutdown.</code>. <code>Standby()</code> / <code>Start()</code> is the pause-and-resume pair. Shutdown does remove the scheduler from the repository, so a subsequent <code>StdSchedulerFactory.GetScheduler()</code> builds a fresh one rather than handing back the corpse — but it is a new scheduler, not a revived one.</p><p><strong>A per-tenant thread pool is a real cost.</strong> Under the scheduler-per-tenant model each tenant gets a scheduling loop that wakes on its own idle timer, a thread pool, and — with a persistent store — a connection pool and a cluster check-in. That is fine for tens of tenants and not for thousands.</p><h2 id="onboarding-a-tenant-while-the-process-runs" tabindex="-1"><a class="header-anchor" href="#onboarding-a-tenant-while-the-process-runs"><span>Onboarding a tenant while the process runs</span></a></h2><p>Under the group-per-tenant model this is a non-question: scheduling a job for a new group is an ordinary API call.</p><p>Under the scheduler-per-tenant model it is still possible, because on 3.x scheduler construction is not bound to the DI container. <code>AddQuartz</code> mutates <code>IServiceCollection</code>, which is closed once the container is built — but <code>StdSchedulerFactory</code> will build a scheduler from a <code>NameValueCollection</code> at any time:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">NameValueCollection</span> props <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.scheduler.instanceName&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> tenantId<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.threadPool.maxConcurrency&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;5&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.jobStore.type&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;Quartz.Impl.AdoJobStore.JobStoreTX, Quartz&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.jobStore.tablePrefix&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;QRTZ_&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.jobStore.dataSource&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.dataSource.default.connectionString&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> connectionStrings<span class="token punctuation">[</span>tenantId<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.dataSource.default.provider&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;SqlServer&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">IScheduler</span> scheduler <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">StdSchedulerFactory</span><span class="token punctuation">(</span>props<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">GetScheduler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>DirectSchedulerFactory.Instance.CreateScheduler(name, instanceId, threadPool, jobStore)</code> does the same with hand-built parts and no property strings.</p><p>Three things you take on by doing this:</p><ul><li><strong>The repository split.</strong> Both routes bind into the static <code>SchedulerRepository.Instance</code>, not the container&#39;s <code>ISchedulerRepository</code> — so the new scheduler will not appear in <code>ISchedulerRepository.LookupAll()</code> or in the Dashboard. To join them, subclass <code>StdSchedulerFactory</code> and override <code>protected virtual ISchedulerRepository GetSchedulerRepository()</code> to return the container&#39;s instance.</li><li><strong>Its lifetime is yours.</strong> The hosted service enumerates named schedulers once at start; a scheduler created afterwards is not started, stopped or shut down by the host. Register an <code>IHostApplicationLifetime.ApplicationStopping</code> callback, or an <code>IHostedService</code> of your own.</li><li><strong>Job resolution.</strong> A bare <code>StdSchedulerFactory</code> uses <code>PropertySettingJobFactory</code>, which activates job types directly and needs a public parameterless constructor. For container-resolved jobs, set <code>scheduler.JobFactory = new MicrosoftDependencyInjectionJobFactory(serviceProvider, options)</code> before starting it.</li></ul><h2 id="see-also" tabindex="-1"><a class="header-anchor" href="#see-also"><span>See also</span></a></h2>`,15),e(`ul`,null,[e(`li`,null,[c(h,{to:`/documentation/tenancy-patterns.html`},{default:i(()=>[...l[27]||=[r(`Tenancy Patterns`,-1)]]),_:1}),l[28]||=r(` — prior art, the deciding axes, and the anti-patterns`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-3.x/packages/multiple-schedulers.html`},{default:i(()=>[...l[29]||=[r(`Multiple Schedulers`,-1)]]),_:1}),l[30]||=r(` — the mechanics of naming and keying schedulers`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-3.x/tutorial/execution-groups.html`},{default:i(()=>[...l[31]||=[r(`Execution Groups`,-1)]]),_:1}),l[32]||=r(` — per-node thread limits in full`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-3.x/tutorial/node-affinity.html`},{default:i(()=>[...l[33]||=[r(`Node Affinity`,-1)]]),_:1}),l[34]||=r(` — pinning triggers to nodes, persisted and cluster-aware`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-3.x/tutorial/advanced-enterprise-features.html`},{default:i(()=>[...l[35]||=[r(`Clustering`,-1)]]),_:1}),l[36]||=r(` — what a shared database gives you`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-3.x/packages/microsoft-di-integration.html`},{default:i(()=>[...l[37]||=[r(`Microsoft DI Integration`,-1)]]),_:1}),l[38]||=r(` — job factories and scopes`,-1)])])])}var p=s(u,[[`render`,f]]);export{l as _pageData,p as default};